INSERT INTO "system_settings" ("key","value","value_type","category","label","description","updated_at","updated_by") VALUES('follow_up_day3_sms','Just checking in on your estimate for {{job_type}} at {{property_address}}. Your quote is valid until {{expiration_date}}. View it here: {{estimate_link}}','string','notifications','Day 3 Follow-Up (SMS)','Sent 3 days after estimate delivery if no response.','2026-06-27 01:16:50',NULL);
INSERT INTO "system_settings" ("key","value","value_type","category","label","description","updated_at","updated_by") VALUES('follow_up_day3_email','{"subject":"Following up on your estimate","body":"Hi {{client_first_name}},\n\nJust wanted to check in on the estimate we sent for {{job_type}} at {{property_address}}. Your quote is valid until {{expiration_date}}.\n\nView and approve it here: {{estimate_link}}\n\nLet me know if you have any questions!\n\nTony Columbus\nColumbus Home Solutions\n501-263-2050"}','json','notifications','Day 3 Follow-Up (Email)','Sent 3 days after estimate delivery if no response.','2026-06-27 01:16:50',NULL);
INSERT INTO "system_settings" ("key","value","value_type","category","label","description","updated_at","updated_by") VALUES('follow_up_day5_sms','Hi {{client_first_name}}, wanted to follow up on your estimate for {{job_type}}. Any questions I can answer? {{estimate_link}}','string','notifications','Day 5 Follow-Up (SMS)','Sent 5 days after estimate delivery if no response.','2026-06-27 01:16:50',NULL);
INSERT INTO "system_settings" ("key","value","value_type","category","label","description","updated_at","updated_by") VALUES('follow_up_day5_email','{"subject":"Still thinking it over?","body":"Hi {{client_first_name}},\n\nI wanted to follow up on your estimate for {{job_type}} at {{property_address}}. Happy to answer any questions or walk you through the scope.\n\nView your estimate here: {{estimate_link}}\n\nTony Columbus\nColumbus Home Solutions\n501-263-2050"}','json','notifications','Day 5 Follow-Up (Email)','Sent 5 days after estimate delivery if no response.','2026-06-27 01:16:50',NULL);
INSERT INTO "system_settings" ("key","value","value_type","category","label","description","updated_at","updated_by") VALUES('follow_up_day7_sms','Hi {{client_first_name}}, your estimate for {{job_type}} expires soon. Ready to move forward? {{estimate_link}}','string','notifications','Day 7 Follow-Up (SMS)','Sent 7 days after estimate delivery if no response.','2026-06-27 01:16:50',NULL);
INSERT INTO "system_settings" ("key","value","value_type","category","label","description","updated_at","updated_by") VALUES('follow_up_day7_email','{"subject":"Your estimate is expiring soon","body":"Hi {{client_first_name}},\n\nYour estimate for {{job_type}} at {{property_address}} is expiring soon. If you''re ready to move forward, you can approve and pay your deposit here: {{estimate_link}}\n\nIf you have questions or need to adjust the timeline, just reply to this email.\n\nTony Columbus\nColumbus Home Solutions\n501-263-2050"}','json','notifications','Day 7 Follow-Up (Email)','Sent 7 days after estimate delivery if no response.','2026-06-27 01:16:50',NULL);
INSERT INTO "system_settings" ("key","value","value_type","category","label","description","updated_at","updated_by") VALUES('follow_up_day10_sms','Hi {{client_first_name}}, this is our final follow-up on your estimate for {{job_type}}. Let us know if you''d like to move forward: {{estimate_link}}','string','notifications','Day 10 Follow-Up (SMS)','Final follow-up sent 10 days after estimate delivery.','2026-06-27 01:16:50',NULL);
INSERT INTO "system_settings" ("key","value","value_type","category","label","description","updated_at","updated_by") VALUES('follow_up_day10_email','{"subject":"Final follow-up on your estimate","body":"Hi {{client_first_name}},\n\nThis is our last follow-up on the estimate for {{job_type}} at {{property_address}}. We''d love the opportunity to work with you — if you''re ready to move forward or have questions, please reach out.\n\nView your estimate: {{estimate_link}}\n\nTony Columbus\nColumbus Home Solutions\n501-263-2050"}','json','notifications','Day 10 Follow-Up (Email)','Final follow-up. Sequence ends after this touch.','2026-06-27 01:16:50',NULL);
INSERT INTO "system_settings" ("key","value","value_type","category","label","description","updated_at","updated_by") VALUES('outreach_day1_sms','Hey {{client_first_name}}, this is Tony with Columbus Home Solutions! Thanks for reaching out — we just received your request about your {{job_type}} project and would love to connect. Do you have a few minutes to chat today?','string','notifications','New Lead Outreach — Day 1 (SMS)','Sent same day the lead comes in, if no appointment is set.','2026-06-27 20:00:02','tony@homesolutionsar.com');
INSERT INTO "system_settings" ("key","value","value_type","category","label","description","updated_at","updated_by") VALUES('outreach_day2_sms','Hey {{client_first_name}}, it''s Tony again with Columbus Home Solutions. Just following up on your {{job_type}} project — is there a better time to reach you, or would texting work better?','string','notifications','New Lead Outreach — Day 2 (SMS)','Sent on Day 2 after lead intake, if no appointment is set.','2026-06-27 20:00:08','tony@homesolutionsar.com');
INSERT INTO "system_settings" ("key","value","value_type","category","label","description","updated_at","updated_by") VALUES('outreach_day3_sms','Hey {{client_first_name}}, don''t mean to bug you — just wanted to reach out one more time about the {{job_type}} project you were interested in. Let me know if you''d still like to chat and we''ll make it happen!','string','notifications','New Lead Outreach — Day 3 (SMS)','Final automated text. Sent on Day 3 if still no appointment. Sequence ends after this.','2026-06-27 20:00:50','tony@homesolutionsar.com');
INSERT INTO "system_settings" ("key","value","value_type","category","label","description","updated_at","updated_by") VALUES('post_visit_sms','Hey {{client_first_name}}, it was great meeting with you today! We''re working on your estimate for the {{job_type}} project and will have it over to you within the next couple of days. Let us know if you have any questions in the meantime!','string','notifications','Post-Visit Follow-Up (SMS)','Sent when estimate visit is marked complete.','2026-06-27 20:01:41','tony@homesolutionsar.com');
