INSERT INTO "document_templates" ("id","name","template_type","content","merge_fields","is_active","version","created_at","updated_at","previous_version_id") VALUES('tpl-s15-service','Service Agreement','service_agreement',replace('{{company_name}}\nSERVICE AGREEMENT\nResidential Construction & Remodeling\n\nClient: {{client_name}}\nProperty Address: {{property_address}}\nProject: {{job_title}}\nContract Total: {{contract_total}}\nDate: {{today_date}}\n\nThis Service Agreement is entered into between {{company_name}} ("Contractor") and the Client named above for the construction and/or remodeling work described in the attached Estimate and Scope of Work.\n\n1. SCOPE OF WORK\nContractor will perform the work described in the project estimate and scope of work attached to this Agreement. Any work not explicitly described is not included in the contract price.\n\n4. PAYMENT TERMS\nThe total contract price is {{contract_total}}, payable according to the following schedule:\n{{payment_schedule}}\nAll invoices are due within seven (7) days of receipt.\n\n8. WARRANTY\nContractor provides a one-year workmanship warranty on completed work beginning at project completion.\n\nBy signing below (in person or electronically), both parties agree to all terms stated in this document. This Agreement is governed by the laws of the State of Arkansas.','\n',char(10)),'["company_name","client_name","property_address","job_title","contract_total","today_date","payment_schedule"]',1,1,'2026-06-02 22:28:55','2026-06-02 22:28:55',NULL);
INSERT INTO "document_templates" ("id","name","template_type","content","merge_fields","is_active","version","created_at","updated_at","previous_version_id") VALUES('tpl-s15-costplus','Cost-Plus Billing Agreement','cost_plus_agreement',replace('{{company_name}}\nCOST-PLUS BILLING AGREEMENT\nPay-As-You-Progress Construction Billing\n\nClient: {{client_name}}\nProperty Address: {{property_address}}\nProject: {{job_title}}\nEstimated Total: {{contract_total}} (estimate only — actual costs billed at cost)\nDate: {{today_date}}\n\n1. HOW COST-PLUS PRICING WORKS\nYou pay the actual cost of materials, labor, and subcontractors — plus a contractor fee. There is no markup on materials or subcontractor costs.\n\n4. DEPOSIT & FINAL PAYMENT\nA deposit of {{deposit_amount}} is required to schedule the project and is applied toward total project costs.\n\nThis Cost-Plus Billing Agreement is supplemental to the Service Agreement and is governed by the laws of the State of Arkansas.','\n',char(10)),'["company_name","client_name","property_address","job_title","contract_total","deposit_amount","today_date"]',1,1,'2026-06-02 22:28:55','2026-06-02 22:28:55',NULL);
INSERT INTO "document_templates" ("id","name","template_type","content","merge_fields","is_active","version","created_at","updated_at","previous_version_id") VALUES('tpl-s15-changeorder','Change Order','change_order',replace('{{company_name}}\nCHANGE ORDER\n\nClient: {{client_name}}\nProperty Address: {{property_address}}\nProject: {{job_title}}\nDate: {{today_date}}\n\nThis Change Order documents a modification to the agreed scope of work, including the change described, its cost impact, and any effect on the project timeline. It requires Client signature before the modified work proceeds.','\n',char(10)),'["company_name","client_name","property_address","job_title","today_date"]',0,1,'2026-06-02 22:28:55','2026-06-02T22:29:46.093Z',NULL);
INSERT INTO "document_templates" ("id","name","template_type","content","merge_fields","is_active","version","created_at","updated_at","previous_version_id") VALUES('tpl-s15-lienwaiver','Lien Waiver','lien_waiver',replace('{{company_name}}\nLIEN WAIVER AND RELEASE\n\nProject: {{job_title}}\nProperty Address: {{property_address}}\nSubcontractor: {{sub_name}}\nWaiver Type: {{waiver_type}}\nPayment Amount: {{payment_amount}}\nDate: {{today_date}}\n\nThe undersigned subcontractor acknowledges receipt of the payment amount stated above and, to that extent, waives and releases any mechanic''s lien, stop-payment notice, or bond right against the property described above for labor and materials furnished through the date of this waiver.','\n',char(10)),'["company_name","job_title","property_address","sub_name","waiver_type","payment_amount","today_date"]',1,1,'2026-06-02 22:28:55','2026-06-02 22:28:55',NULL);
INSERT INTO "document_templates" ("id","name","template_type","content","merge_fields","is_active","version","created_at","updated_at","previous_version_id") VALUES('tpl-s15-warranty','Warranty Certificate','other',replace('{{company_name}}\nCERTIFICATE OF WARRANTY\n\nClient: {{client_name}}\nProperty Address: {{property_address}}\nProject: {{job_title}}\nIssued: {{today_date}}\n\n{{company_name}} warrants the workmanship of the completed project described above for a period of one (1) year from the date of project completion, covering defects in workmanship (excluding normal wear, owner/third-party damage, improper maintenance, and manufacturer-covered material defects).','\n',char(10)),'["company_name","client_name","property_address","job_title","today_date"]',1,1,'2026-06-02 22:28:55','2026-06-02 22:28:55',NULL);
INSERT INTO "document_templates" ("id","name","template_type","content","merge_fields","is_active","version","created_at","updated_at","previous_version_id") VALUES('4640ba76-fbaf-411c-959e-234729dfd1f5','Change Order','change_order',replace('{{company_name}}\nCHANGE ORDER\n\nClient: {{client_name}}\nProperty Address: {{property_address}}\nProject: {{job_title}}\nDate: {{today_date}}\n\nThis Change Order documents a modification to the agreed scope of work, including the change described, its cost impact, and any effect on the project timeline. It requires Client signature before the modified work proceeds.','\n',char(10)),'["company_name","client_name","property_address","job_title","today_date"]',1,2,'2026-06-02T22:29:46.093Z','2026-06-02T22:29:46.093Z','tpl-s15-changeorder');
