INSERT INTO "notification_templates" ("id","trigger_event","name","recipient_type","channel","subject","body_template","merge_fields","is_active","delay_minutes","send_time","phase","sort_order","created_at","updated_at") VALUES('nt-lead-created-sms','lead_created','Lead Acknowledgment','client','sms',NULL,replace('Lead Acknowledgment (SMS)\nHey {{client_first_name}}, this is Tony with Columbus Home Solutions! Thanks for reaching out — we just sent you an email with a little more info about us. Are you open to a quick call, or would you prefer to text?','\n',char(10)),'[]',1,0,NULL,'estimating',1,'2026-05-29 19:07:35','2026-06-27T19:53:29.693Z');
INSERT INTO "notification_templates" ("id","trigger_event","name","recipient_type","channel","subject","body_template","merge_fields","is_active","delay_minutes","send_time","phase","sort_order","created_at","updated_at") VALUES('nt-lead-created-email','lead_created','Lead Acknowledgment Email','client','email','Thanks for Reaching Out — Columbus Home Solutions',replace('Hello {{client_first_name}}!\n\nThanks for reaching out to Columbus Home Solutions. We''re excited to learn more about your project and show you why we''re the right fit for the job.\n\nIn the meantime, here are a few links to learn more about us:\n\n⭐ Our Google Reviews: https://share.google/ST7aruadcppobFy5H\n📸 Our Work: https://homesolutionsar.com/services\nℹ️ About CHS: https://homesolutionsar.com/about\n\nCould you let us know a little more about the project you have in mind and the best way to reach you?\n\nWe''ll be in touch very soon — typically within the hour.\n\nThanks,\nTony Columbus\nColumbus Home Solutions\n501-263-2050\nhomesolutionsar.com','\n',char(10)),'[]',1,0,NULL,'estimating',2,'2026-05-29 19:07:35','2026-06-27T19:57:34.062Z');
INSERT INTO "notification_templates" ("id","trigger_event","name","recipient_type","channel","subject","body_template","merge_fields","is_active","delay_minutes","send_time","phase","sort_order","created_at","updated_at") VALUES('nt-appointment-confirmed-sms','appointment_confirmed','Appointment Confirmation','client','sms',NULL,'Hey {{client_first_name}}, great talking with you! You''re confirmed for an in-home consultation with Tony on {{appointment_date}} at {{appointment_time}}. We''ll see you then — reach out if anything comes up!','["appointment_date","appointment_time","property_address"]',1,0,NULL,'estimating',3,'2026-05-29 19:07:35','2026-06-27T19:57:51.748Z');
INSERT INTO "notification_templates" ("id","trigger_event","name","recipient_type","channel","subject","body_template","merge_fields","is_active","delay_minutes","send_time","phase","sort_order","created_at","updated_at") VALUES('nt-appointment-confirmed-email','appointment_confirmed','Appointment Confirmation Email','client','email','You''re Confirmed — Columbus Home Solutions Consultation on {{appointment_date}}',replace('Hello {{client_first_name}}!\n\nIt was great chatting with you today. We''re looking forward to meeting with you about your {{job_type}} project!\n\n📅 Your consultation is confirmed for:\n{{appointment_date}} at {{appointment_time}}\n{{property_address}}\n\nTony Columbus will be there to walk through the project with you, take measurements, and answer any questions you have. From there, we''ll put together a detailed estimate for your review.\n\nA few things that help us hit the ground running:\n- If you have any inspiration photos or material preferences, feel free to have them handy\n- If you know the square footage of the area, great — if not, we''ll measure it together\n- Any questions you think of before then, just text or call: 501-263-2050\n\nWe''re looking forward to meeting you!\n\nTony Columbus\nColumbus Home Solutions\n501-263-2050\nhomesolutionsar.com\n\n⭐ See what our clients say: https://share.google/ST7aruadcppobFy5H','\n',char(10)),'["appointment_date","appointment_time","property_address"]',1,0,NULL,'estimating',4,'2026-05-29 19:07:35','2026-06-27T19:58:52.743Z');
